import {
  Entity,
  PrimaryGeneratedColumn,
  Column,
  CreateDateColumn,
  UpdateDateColumn,
  DeleteDateColumn,
} from 'typeorm';

export enum CompanyStatus {
  ACTIVE = '1',
  INACTIVE = '0',
  PENDING = '2',
}

export enum Industry {
  TECHNOLOGY = 'TECHNOLOGY',
  FINANCE = 'FINANCE',
  MANUFACTURING = 'MANUFACTURING',
  RETAIL = 'RETAIL',
  OTHER = 'OTHER',
}

@Entity('companies')
export class CompanyEntity {
  @PrimaryGeneratedColumn('uuid')
  id: string;

  @Column({ type: 'varchar', length: 255, comment: 'Company Name' })
  name: string;

  @Column({
    type: 'varchar',
    length: 255,
    nullable: true,
    comment: 'Company Email Address',
  })
  email: string;

  @Column({
    type: 'varchar',
    length: 50,
    nullable: true,
    comment: 'Contact Phone Number',
  })
  phone: string;

  @Column({
    type: 'varchar',
    length: 255,
    nullable: true,
    comment: 'Company Website',
  })
  website: string;

  @Column({
    type: 'enum',
    enum: CompanyStatus,
    default: CompanyStatus.PENDING,
    comment: 'Company Status',
  })
  status: CompanyStatus;

  @Column({
    type: 'enum',
    enum: Industry,
    nullable: true,
    comment: 'Associated Industry',
  })
  industry: Industry;

  @Column({
    type: 'timestamptz',
    nullable: true,
    comment: 'Last Contacted At (for projection)',
  })
  lastContactedAt: Date;

  @CreateDateColumn({ type: 'timestamptz', comment: 'Creation Timestamp' })
  createdAt: Date;

  @UpdateDateColumn({ type: 'timestamptz', comment: 'Update Timestamp' })
  updatedAt: Date;

  @DeleteDateColumn({
    type: 'timestamptz',
    nullable: true,
    select: false,
    comment: 'Soft Delete Timestamp',
  })
  deletedAt: Date;
}
import {
  Controller,
  Delete,
  Get,
  Post,
  Body,
  Param,
  Query,
  HttpCode,
  HttpStatus,
} from '@nestjs/common';
import { CompanyService } from './company.service';
import { CreateCompanyDto, UpdateCompanyDto } from './dto';
import { createUuidV4Pipe } from '../../common/pipes/uuid-v4.pipe';

@Controller('companies')
export class CompanyController {
  constructor(private readonly companyService: CompanyService) {}
  /**
   * create a new company
   * POST /api/companies
   */
  @Post()
  async create(@Body() createCompanyDto: CreateCompanyDto) {
    const newCompany =
      await this.companyService.createCompany(createCompanyDto);

    return {
      success: true,
      message: 'Company created successfully',
      companyId: newCompany.id,
    };
  }

  /**
   * GET /api/companies?page=1&limit=10&status=active&industry=IT
   */
  @Get()
  findAll(
    @Query('page') page: string = '1',
    @Query('pageSize') pageSize: string = '10',
    @Query('status') status?: string,
    @Query('industry') industry?: string,
  ) {
    return this.companyService.getCompanies(
      Number(page),
      Number(pageSize),
      status,
      industry,
    );
  }

  /**
   * Get company details by ID
   * GET /api/companies/:id
   */
  @Get(':id')
  findOne(@Param('id', createUuidV4Pipe()) id: string) {
    return this.companyService.getCompanyById(id);
  }

  /**
   * Update a company partially
   * POST /api/companies/:id
   */
  @Post(':id')
  update(
    @Param('id', createUuidV4Pipe()) id: string,
    @Body() updateCompanyDto: UpdateCompanyDto,
  ) {
    return this.companyService.updateCompany(id, updateCompanyDto);
  }

  @Delete(':id')
  @HttpCode(HttpStatus.NO_CONTENT)
  remove(@Param('id', createUuidV4Pipe()) id: string): Promise<void> {
    return this.companyService.removeCompany(id);
  }
}
import { HttpStatus, Injectable } from '@nestjs/common';
import { CompanyRepository } from './company.repository';
import { CreateCompanyDto } from './dto/create.dto';
import { UpdateCompanyDto } from './dto/update.dto';
import { CompanyEntity, CompanyStatus, Industry } from './company.entity';
import { AppException } from '../../common/errors/app-exception';
import { BUSINESS_ERROR_CODES } from '../../common/errors/error-codes';

type CompanyFilter = {
  status?: CompanyStatus;
  industry?: Industry;
};

@Injectable()
export class CompanyService {
  constructor(private readonly companyRepo: CompanyRepository) {}

  /**
   * Create a new company
   */
  async createCompany(dto: CreateCompanyDto): Promise<CompanyEntity> {
    const newCompany = this.companyRepo.create(dto);
    return await this.companyRepo.save(newCompany);
  }

  /**
   * Get a paginated list of companies
   */
  async getCompanies(
    page: number,
    limit: number,
    status?: string,
    industry?: string,
  ) {
    const whereCondition: CompanyFilter = {};

    if (industry && Object.values(Industry).includes(industry as Industry)) {
      whereCondition.industry = industry as Industry;
    }

    if (
      status &&
      Object.values(CompanyStatus).includes(status as CompanyStatus)
    ) {
      whereCondition.status = status as CompanyStatus;
    }

    // (If you need fuzzy search, you'd use TypeORM's ILike operator here)

    return await this.companyRepo.paginate(page, limit, {
      where: whereCondition,
      order: { createdAt: 'DESC' }, // Default sorting
    });
  }

  /**
   * Get company details by ID
   */
  async getCompanyById(id: string): Promise<CompanyEntity> {
    const company = await this.companyRepo.findOne({ where: { id } });

    if (!company) {
      throw new AppException({
        statusCode: HttpStatus.NOT_FOUND,
        code: BUSINESS_ERROR_CODES.ENTITY_NOT_FOUND,
        message: `Company with ID ${id} not found`,
        details: {
          resource: 'Company',
          id,
        },
      });
    }

    return company;
  }

  /**
   * Partially update a company
   */
  async updateCompany(
    id: string,
    dto: UpdateCompanyDto,
  ): Promise<CompanyEntity> {
    // First, ensure the company exists
    const company = await this.getCompanyById(id);

    // Merge the new data into the existing entity and save
    const updatedCompany = this.companyRepo.merge(company, dto);
    return await this.companyRepo.save(updatedCompany);
  }

  /**
   * Delete a company when no active contacts remain
   */
  async removeCompany(id: string): Promise<void> {
    await this.getCompanyById(id);

    const activeContactCount = await this.companyRepo.manager
      .createQueryBuilder()
      .from('contacts', 'contact')
      .where('contact.companyId = :id', { id })
      .getCount();

    if (activeContactCount > 0) {
      throw new AppException({
        statusCode: HttpStatus.CONFLICT,
        code: BUSINESS_ERROR_CODES.REFERENTIAL_INTEGRITY_VIOLATION,
        message: 'Cannot delete company with existing contacts.',
        details: {
          resource: 'Company',
          id,
          blockingChildren: {
            contacts: activeContactCount,
          },
        },
      });
    }

    await this.companyRepo.softDelete(id);
  }
}
