import { HttpException, HttpStatus, Injectable } from '@nestjs/common';
import { ContactRepository } from './contact.repository';
import { CreateContactDto, UpdateContactDto, ContactListQueryDto } from './dto';
import { ContactEntity } from './contact.entity';
import { CompanyService } from '../company/company.module';
import { AppException } from '../../common/errors/app-exception';
import { BUSINESS_ERROR_CODES } from '../../common/errors/error-codes';

@Injectable()
export class ContactService {
  constructor(
    private readonly contactRepository: ContactRepository,
    private readonly companyService: CompanyService,
  ) {}

  /**
   * create a new contact
   */
  async createContact(dto: CreateContactDto): Promise<ContactEntity> {
    try {
      await this.companyService.getCompanyById(dto.companyId);
    } catch (error) {
      if (error instanceof HttpException && error.getStatus() === 404) {
        throw new AppException({
          statusCode: HttpStatus.NOT_FOUND,
          code: BUSINESS_ERROR_CODES.PARENT_NOT_FOUND,
          message: `Company with ID ${dto.companyId} not found`,
          details: {
            resource: 'Company',
            id: dto.companyId,
          },
        });
      }

      throw error;
    }

    const contact = this.contactRepository.create(dto);
    return await this.contactRepository.save(contact);
  }

  /**
   * get contacts list
   */
  async getContactsList(query: ContactListQueryDto) {
    const [items, total] = await this.contactRepository.findWithFilter(query);

    const limit = query.pageSize ?? 20;
    const page = query.page ?? 1;

    return {
      items,
      total,
      page,
      pageSize: limit,
      totalPages: Math.ceil(total / limit),
    };
  }

  /**
   *  get detailed contact information
   */
  async getContactById(id: string): Promise<ContactEntity> {
    const contact = await this.contactRepository.findOne({ where: { id } });

    if (!contact) {
      throw new AppException({
        statusCode: HttpStatus.NOT_FOUND,
        code: BUSINESS_ERROR_CODES.ENTITY_NOT_FOUND,
        message: `Contact with ID ${id} not found`,
        details: {
          resource: 'Contact',
          id,
        },
      });
    }

    return contact;
  }

  /**
   * update a contact
   */
  async updateContact(
    id: string,
    dto: UpdateContactDto & { companyId?: string },
  ): Promise<ContactEntity> {
    // ensure the contact exists
    const contact = await this.getContactById(id);

    if (dto.companyId && dto.companyId !== contact.companyId) {
      try {
        await this.companyService.getCompanyById(dto.companyId);
      } catch (error) {
        if (error instanceof HttpException && error.getStatus() === 404) {
          throw new AppException({
            statusCode: HttpStatus.NOT_FOUND,
            code: BUSINESS_ERROR_CODES.PARENT_NOT_FOUND,
            message: `Company with ID ${dto.companyId} not found`,
            details: {
              resource: 'Company',
              id: dto.companyId,
            },
          });
        }

        throw error;
      }
    }

    const updatedContact = this.contactRepository.merge(contact, dto);

    return await this.contactRepository.save(updatedContact);
  }

  /**
   * soft delete a contact
   */
  async removeContact(id: string): Promise<void> {
    await this.getContactById(id);
    await this.contactRepository.softDelete(id);
  }

  async findWithCompany(id: string) {
    const contact = await this.getContactById(id);
    const company = await this.companyService.getCompanyById(contact.companyId);
    return { ...contact, company };
  }
}
import { Injectable } from '@nestjs/common';
import { DataSource, Brackets } from 'typeorm';
import { BaseRepository } from '../../core/database/base.repository';
import { ContactEntity } from './contact.entity';
import { ContactListQueryDto } from './dto';

@Injectable()
export class ContactRepository extends BaseRepository<ContactEntity> {
  constructor(private dataSource: DataSource) {
    super(ContactEntity, dataSource.createEntityManager());
  }

  async findWithFilter(query: ContactListQueryDto) {
    const queryBuilder = this.createQueryBuilder('contact');

    const sortField = query.sort
      ? `contact.${query.sort}`
      : 'contact.createdAt';
    const sortOrder = query.order ? query.order.toUpperCase() : 'DESC';
    queryBuilder.orderBy(sortField, sortOrder as 'ASC' | 'DESC');

    if (query.companyId) {
      queryBuilder.andWhere('contact.companyId = :companyId', {
        companyId: query.companyId,
      });
    }

    if (query.q) {
      const searchValue = `%${query.q}%`;
      queryBuilder.andWhere(
        new Brackets((qb) => {
          qb.where('contact.name ILIKE :searchValue', { searchValue })
            .orWhere('contact.email ILIKE :searchValue', { searchValue })
            .orWhere('contact.phone ILIKE :searchValue', { searchValue })
            .orWhere('contact.role ILIKE :searchValue', { searchValue });
        }),
      );
    }

    if (query.role) {
      queryBuilder.andWhere('contact.role = :role', { role: query.role });
    }

    const offset = query.offset ?? 0;
    const limit = query.limit ?? 20;

    return queryBuilder.skip(offset).take(limit).getManyAndCount();
  }
}
import { HttpStatus } from '@nestjs/common';

export const BUSINESS_ERROR_CODES = {
  VALIDATION_ERROR: 'VALIDATION_ERROR',
  INVALID_UUID: 'INVALID_UUID',
  ENTITY_NOT_FOUND: 'ENTITY_NOT_FOUND',
  PARENT_NOT_FOUND: 'PARENT_NOT_FOUND',
  IMMUTABLE_FIELD: 'IMMUTABLE_FIELD',
  REFERENTIAL_INTEGRITY_VIOLATION: 'REFERENTIAL_INTEGRITY_VIOLATION',
} as const;

export type BusinessErrorCode =
  (typeof BUSINESS_ERROR_CODES)[keyof typeof BUSINESS_ERROR_CODES];

export const BUSINESS_ERROR_CATALOG: Record<
  BusinessErrorCode,
  {
    defaultStatusCode: number;
    description: string;
  }
> = {
  VALIDATION_ERROR: {
    defaultStatusCode: HttpStatus.BAD_REQUEST,
    description: 'Request payload or query validation failed.',
  },
  INVALID_UUID: {
    defaultStatusCode: HttpStatus.BAD_REQUEST,
    description: 'A route parameter is not a valid UUID v4.',
  },
  ENTITY_NOT_FOUND: {
    defaultStatusCode: HttpStatus.NOT_FOUND,
    description: 'The requested entity does not exist.',
  },
  PARENT_NOT_FOUND: {
    defaultStatusCode: HttpStatus.NOT_FOUND,
    description: 'The required parent entity does not exist.',
  },
  IMMUTABLE_FIELD: {
    defaultStatusCode: HttpStatus.UNPROCESSABLE_ENTITY,
    description: 'The request attempts to modify an immutable field.',
  },
  REFERENTIAL_INTEGRITY_VIOLATION: {
    defaultStatusCode: HttpStatus.CONFLICT,
    description: 'The operation is blocked by related records.',
  },
};
import {
  ExceptionFilter,
  Catch,
  ArgumentsHost,
  HttpException,
  HttpStatus,
} from '@nestjs/common';
import { Request, Response } from 'express';
import { AppExceptionPayload } from '../errors/app-exception';
import { BUSINESS_ERROR_CODES } from '../errors/error-codes';

type ExceptionResponsePayload = {
  code?: string;
  message?: string | string[];
  details?: unknown;
};

const isExceptionResponsePayload = (
  value: unknown,
): value is ExceptionResponsePayload => {
  return typeof value === 'object' && value !== null;
};

@Catch(HttpException)
export class HttpExceptionFilter implements ExceptionFilter {
  catch(exception: HttpException, host: ArgumentsHost) {
    const ctx = host.switchToHttp();
    const response = ctx.getResponse<Response>();
    const request = ctx.getRequest<Request>();

    // Get the HTTP status code from the exception (e.g., 400, 404, 500)
    const status = exception.getStatus();

    // Get the detailed response content from the exception
    const exceptionResponse: unknown = exception.getResponse();
    const payload = isExceptionResponsePayload(exceptionResponse)
      ? exceptionResponse
      : undefined;

    // Extract error message
    const message = payload?.message ? payload.message : exception.message;
    const normalizedMessage = Array.isArray(message) ? message[0] : message;
    const code = payload?.code ?? defaultErrorCode(status);
    const details = payload?.details;

    response.status(status).json({
      success: false,
      statusCode: status,
      code,
      message: normalizedMessage,
      details,
      timestamp: new Date().toISOString(),
      path: request.url,
    });
  }
}

function defaultErrorCode(status: number): AppExceptionPayload['code'] {
  const errorCodeByStatus: Partial<
    Record<number, AppExceptionPayload['code']>
  > = {
    [HttpStatus.BAD_REQUEST]: BUSINESS_ERROR_CODES.VALIDATION_ERROR,
    [HttpStatus.NOT_FOUND]: BUSINESS_ERROR_CODES.ENTITY_NOT_FOUND,
    [HttpStatus.UNPROCESSABLE_ENTITY]: BUSINESS_ERROR_CODES.IMMUTABLE_FIELD,
    [HttpStatus.CONFLICT]: BUSINESS_ERROR_CODES.REFERENTIAL_INTEGRITY_VIOLATION,
  };

  return errorCodeByStatus[status] ?? BUSINESS_ERROR_CODES.VALIDATION_ERROR;
}
import { HttpStatus, ValidationError } from '@nestjs/common';
import { AppException } from './app-exception';
import { BUSINESS_ERROR_CODES } from './error-codes';

type FormattedValidationError = {
  field: string;
  messages: string[];
};

export function createValidationException(errors: ValidationError[]) {
  const formattedErrors = flattenValidationErrors(errors);
  const firstMessage =
    formattedErrors[0]?.messages[0] ?? 'Request validation failed.';

  return new AppException({
    statusCode: HttpStatus.BAD_REQUEST,
    code: BUSINESS_ERROR_CODES.VALIDATION_ERROR,
    message: firstMessage,
    details: {
      errors: formattedErrors,
    },
  });
}

function flattenValidationErrors(
  errors: ValidationError[],
  parentPath?: string,
): FormattedValidationError[] {
  return errors.flatMap((error) => {
    const field = parentPath
      ? `${parentPath}.${error.property}`
      : error.property;
    const messages = error.constraints ? Object.values(error.constraints) : [];
    const currentError = messages.length > 0 ? [{ field, messages }] : [];
    const childErrors = error.children
      ? flattenValidationErrors(error.children, field)
      : [];

    return [...currentError, ...childErrors];
  });
}
import type { PaginatedResult } from '../types/paginated-result.type';

const DEFAULT_PAGE = 1;
const DEFAULT_PAGE_SIZE = 10;
const MAX_PAGE_SIZE = 100;

export type PaginationQueryInput = {
  page?: number | string;
  pageSize?: number | string;
};

export function resolvePagination(query: PaginationQueryInput) {
  const page = normalizePositiveInteger(query.page, DEFAULT_PAGE);
  const pageSize = Math.min(
    normalizePositiveInteger(query.pageSize, DEFAULT_PAGE_SIZE),
    MAX_PAGE_SIZE,
  );

  return {
    page,
    pageSize,
    skip: (page - 1) * pageSize,
    take: pageSize,
  };
}

export function buildPaginatedResult<TItem>(args: {
  items: TItem[];
  page: number;
  pageSize: number;
  total: number;
}): PaginatedResult<TItem> {
  const { items, page, pageSize, total } = args;

  return {
    items,
    page,
    pageSize,
    total,
    totalPages: total === 0 ? 0 : Math.ceil(total / pageSize),
  };
}

function normalizePositiveInteger(
  value: number | string | undefined,
  fallback: number,
) {
  const parsedValue =
    typeof value === 'number' ? value : Number.parseInt(value ?? '', 10);

  if (!Number.isFinite(parsedValue) || parsedValue < 1) {
    return fallback;
  }

  return parsedValue;
}
import {
  IsEnum,
  IsInt,
  IsOptional,
  IsString,
  IsUUID,
  Min,
  Max,
} from 'class-validator';
import { Type } from 'class-transformer';

export enum ContactSortField {
  NAME = 'name',
  CREATED_AT = 'createdAt',
}

export enum SortOrder {
  ASC = 'asc',
  DESC = 'desc',
}

export class ContactListQueryDto {
  @IsOptional()
  @IsUUID('4', { message: 'companyId must be a valid UUID' })
  companyId?: string;

  @IsOptional()
  @IsEnum(ContactSortField)
  sort?: ContactSortField = ContactSortField.CREATED_AT;

  @IsOptional()
  @IsEnum(SortOrder)
  order?: SortOrder = SortOrder.DESC;

  @IsOptional()
  @Type(() => Number)
  @IsInt()
  @Min(1)
  @Max(100)
  pageSize?: number = 10;

  @IsOptional()
  @Type(() => Number)
  @IsInt()
  @Min(1)
  page?: number = 1;

  @IsOptional()
  @IsString()
  q?: string;

  @IsOptional()
  @IsString()
  role?: string;

  @IsOptional()
  @Type(() => Date)
  lastContactedAt?: Date;

  get offset(): number {
    return ((this.page || 1) - 1) * (this.pageSize || 10);
  }

  // 计算 limit (take)
  get limit(): number {
    return this.pageSize || 10;
  }
}

