function formatDate(value) {
  if (!value) {
    return '—';
  }

  return new Intl.DateTimeFormat('en', {
    dateStyle: 'medium',
    timeStyle: 'short',
  }).format(new Date(value));
}

function ActionCell({ contact, onView, onEdit, onDelete }) {
  return (
    <TableCell align="right">
      <Stack direction="row" spacing={1} justifyContent="flex-end">
        <Button
          size="small"
          startIcon={<EyeOutlined />}
          onClick={() => onView(contact)}
        >
          View
        </Button>
        <IconButton onClick={() => onEdit(contact)} aria-label="edit">
          <EditOutlined />
        </IconButton>
        <IconButton color="error" onClick={() => onDelete(contact)} aria-label="delete">
          <DeleteOutlined />
        </IconButton>
      </Stack>
    </TableCell>
  );
}

