  return new Intl.DateTimeFormat('en', {
    dateStyle: 'medium',
    timeStyle: 'short',
  }).format(new Date(value));
}

const statusColors = {
  "1": 'success',
  "0": 'default',
  "2": 'warning',
};

const statusLabels = {
  "1": 'Active',
  "0": 'Inactive',
  "2": 'Pending',
};

const industryLabels = {
  TECHNOLOGY: 'Technology',
  FINANCE: 'Finance',
  HEALTHCARE: 'Healthcare',
  RETAIL: 'Retail',
  OTHER: 'Other',
};


function StatusCell({ status }) {
  if (!status) {
    return <TableCell>—</TableCell>;
  }

  return (
    <TableCell>
      <Chip
        label={statusLabels[status] || 'Unknown'}
        color={statusColors[status] || 'default'}
        size="small"
      />
    </TableCell>
  );
}

function IndustryCell({ industry }) {
  if (!industry) {
    return <TableCell>—</TableCell>;
  }

  return (
    <TableCell>
      <Chip
        label={industryLabels[industry] || industry}
        size="small"
        variant="outlined" // 使用描边样式与 Status 区分开
      />
    </TableCell>
  );
}

function ActionCell({ company, onView, onEdit, onDelete }) {
  return (
    <TableCell align="right">
      <Stack direction="row" spacing={1} justifyContent="flex-end">
        <Button
          size="small"
          startIcon={<EyeOutlined />}
          onClick={() => onView(company)}
        >
          View
        </Button>
        <IconButton onClick={() => onEdit(company)} aria-label="edit">
          <EditOutlined />
        </IconButton>
        <IconButton color="error" onClick={() => onDelete(company)} aria-label="delete">
          <DeleteOutlined />
        </IconButton>
      </Stack>
    </TableCell>
  );
}

// main component

export function CompanyTable({ companies, onDelete, onEdit, onView }) {
  return (
    <TableContainer component={Paper} className="crm-table-shell">
      <Table>
        <TableHead>
          <TableRow>
            <TableCell>Company</TableCell>
            <TableCell>Email</TableCell>
            <TableCell>Industry</TableCell> {/* 新增了行业列头 */}
            <TableCell>Status</TableCell>
            <TableCell>Last contacted</TableCell>
            <TableCell>Created</TableCell>
            <TableCell align="right">Actions</TableCell>
          </TableRow>
        </TableHead>
        <TableBody>
          {companies.map((company) => (
            <TableRow key={company.id} hover>
              <TableCell>
                <Stack spacing={0.5}>
                  <Typography fontWeight={600}>{company.name}</Typography>
                  <Typography variant="body2" color="text.secondary">
                    {company.id}
                  </Typography>
                </Stack>
              </TableCell>

              <TableCell>{company.email || '—'}</TableCell>

              <IndustryCell industry={company.industry} />

              <StatusCell status={company.status} />

              <TableCell>{formatDate(company.lastContactedAt)}</TableCell>

              <TableCell>{formatDate(company.createdAt)}</TableCell>

              <ActionCell
                company={company}
                onView={onView}
                onEdit={onEdit}
                onDelete={onDelete}
              />
            </TableRow>
          ))}
        </TableBody>
      </Table>
    </TableContainer>
  );
}import {
  Button,
  IconButton,
  Paper,
  Stack,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
} from '@mui/material';
import DeleteOutlined from '@ant-design/icons/DeleteOutlined';
import EditOutlined from '@ant-design/icons/EditOutlined';
import EyeOutlined from '@ant-design/icons/EyeOutlined';

function formatDate(value) {
  if (!value) {
    return '—';
  }

  return new Intl.DateTimeFormat('en', {
    dateStyle: 'medium',
    timeStyle: 'short',
  }).format(new Date(value));
}

function ActionCell({ contact, onView, onEdit, onDelete }) {
  return (
    <TableCell align="right">
      <Stack direction="row" spacing={1} justifyContent="flex-end">
        <Button
          size="small"
          startIcon={<EyeOutlined />}
          onClick={() => onView(contact)}
        >
          View
        </Button>
        <IconButton onClick={() => onEdit(contact)} aria-label="edit">
          <EditOutlined />
        </IconButton>
        <IconButton color="error" onClick={() => onDelete(contact)} aria-label="delete">
          <DeleteOutlined />
        </IconButton>
      </Stack>
    </TableCell>
  );
}

// --- 主表格组件 ---
export function ContactTable({ contacts, onView, onDelete, onEdit }) {
  return (
    <TableContainer component={Paper} className="crm-table-shell">
      <Table size="small">
        <TableHead>
          <TableRow>
            <TableCell>Name</TableCell>
            <TableCell>Email</TableCell>
            <TableCell>Phone</TableCell>
            <TableCell>Role</TableCell>
            <TableCell>Last Contacted</TableCell>
            <TableCell>Created</TableCell>
            <TableCell align="right">Actions</TableCell>
          </TableRow>
        </TableHead>
        <TableBody>
          {contacts.map((contact) => (
            <TableRow key={contact.id} hover>
              <TableCell>{contact.name}</TableCell>
              <TableCell>{contact.email || '—'}</TableCell>
              <TableCell>{contact.phone || '—'}</TableCell>
              <TableCell>{contact.role || '—'}</TableCell>
              <TableCell>{formatDate(contact.lastContactedAt)}</TableCell>
              <TableCell>{formatDate(contact.createdAt)}</TableCell>

              <ActionCell
                contact={contact}
                onView={onView}
                onEdit={onEdit}
                onDelete={onDelete}
              />
            </TableRow>
          ))}
        </TableBody>
      </Table>
    </TableContainer>
  );
}import {
  useMutation,
  useQuery,
  useQueryClient,
} from '@tanstack/react-query';

import { contactApi } from '../../api/contactApi';

export const contactKeys = {
  all: ['contacts'],
  lists: () => [...contactKeys.all, 'list'],
  list: (companyId, query) => [...contactKeys.lists(), { companyId: companyId ?? 'all', query }],
  details: () => [...contactKeys.all, 'detail'],
  detail: (contactId) => [...contactKeys.details(), contactId],
};

export function useContactList(params = {}) {
  const { companyId, ...query } = params;
  return useQuery({
    queryKey: contactKeys.list(companyId, query),
    queryFn: () => contactApi.list(companyId, query),
  });
}

export function useContact(id) {
  return useQuery({
    queryKey: contactKeys.detail(id),
    queryFn: () => contactApi.get(id),
    enabled: Boolean(id),
  });
}

export function useCreateContact() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: (data) => contactApi.create(data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: contactKeys.lists() });
    },
  });
}

export function useUpdateContact(contactId) {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: ({ id, data }) => contactApi.update(id, data),
    onSuccess: (_, variables) => {
      queryClient.invalidateQueries({ queryKey: contactKeys.lists() });
      queryClient.invalidateQueries({ queryKey: contactKeys.detail(variables.id) });
    },
  });
}

export function useDeleteContact() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: (id) => contactApi.delete(id),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: contactKeys.lists() });
    },
  });
}

