        value: 2500,
        contactId: null,
        expectedCloseDate: null,
      });

    expect(updated.status).toBe(201);
    expect(updated.body.stage).toBe('closed_won');
    expect(Number(updated.body.value)).toBe(2500);
    expect(updated.body.contactId).toBeNull();
    expect(updated.body.expectedCloseDate).toBeNull();

