// modules/company/dto/index.ts
export * from './create.dto';
export * from './update.dto';
export * from './response.dto';

import { Button, Stack, TextField, Typography } from '@mui/material';

import styles from './Toolbar.module.scss';

export function DataTableToolbar({
  actions,
  description,
  filters,
  onReset,
  onSearchChange,
  onSearchSubmit,
  searchPlaceholder,
  searchValue,
  title,
}) {
  return (
    <div className={styles.toolbarShell}>
      <div className={styles.headerRow}>
        <div>
          <Typography variant="h4">{title}</Typography>
          {description ? (
            <Typography className={styles.description}>{description}</Typography>
          ) : null}
        </div>
        {actions ? <div className={styles.actions}>{actions}</div> : null}
      </div>

      <form className={styles.filtersForm} onSubmit={onSearchSubmit}>
        <TextField
          size="small"
          placeholder={searchPlaceholder}
          value={searchValue}
          onChange={(event) => onSearchChange(event.target.value)}
          className={styles.searchField}
        />

        {filters ? <div className={styles.filters}>{filters}</div> : null}

        <Stack direction="row" spacing={1} className={styles.submitActions}>
          <Button type="submit" variant="contained">
            Query
          </Button>
          <Button type="button" onClick={onReset}>
            Reset
          </Button>
        </Stack>
      </form>
    </div>
  );
}

export { DataTableToolbar as Toolbar };

import {
  Alert,
  Box,
  Button,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  MenuItem,
  Snackbar,
  Stack,
  TextField,
  Typography,
} from '@mui/material';
import PlusOutlined from '@ant-design/icons/PlusOutlined';
import { useNavigate } from 'react-router-dom';
import { useState } from 'react';

import { isTransportError } from 'api/request';
import { DataTablePagination } from '../../components/Table/Pagination/Pagination';
import { DataTableShell } from '../../components/Table/Shell/Shell';
import { useCompanyList } from '../companies/companyQueries';
import { DealFormDialog } from './DealForm';
import { DealTable } from './DealTable';
import {
  useCreateDeal,
  useDealList,
  useDeleteDeal,
  useUpdateDeal,
} from './dealQueries';

function extractErrorMessage(error, fallbackMessage) {
  return error?.message || fallbackMessage;
}

export default function DealsPage() {
  const navigate = useNavigate();
  const createDeal = useCreateDeal();
  const updateDeal = useUpdateDeal();
  const deleteDeal = useDeleteDeal();

  const [formState, setFormState] = useState({ open: false, mode: 'create', deal: null });
  const [deleteTarget, setDeleteTarget] = useState(null);
  const [feedback, setFeedback] = useState({ open: false, severity: 'success', message: '' });
  const [listQuery, setListQuery] = useState({
    page: 1,
    pageSize: 10,
    stage: undefined,
    companyId: undefined,
  });

  const dealsQuery = useDealList(listQuery);
  const companiesQuery = useCompanyList({ page: 1, pageSize: 100 });

  const handleFormSubmit = async (payload) => {
    try {
      if (formState.mode === 'create') {
        await createDeal.mutateAsync(payload);
        setFeedback({ open: true, severity: 'success', message: 'Deal created.' });
      } else {
        await updateDeal.mutateAsync({
          id: formState.deal.id,
          data: payload,
        });
        setFeedback({ open: true, severity: 'success', message: 'Deal updated.' });
      }

      setFormState({ open: false, mode: 'create', deal: null });
    } catch (error) {
      if (!isTransportError(error)) {
        setFeedback({
          open: true,
          severity: 'error',
          message: extractErrorMessage(error, 'Deal request failed.'),
        });
      }
    }
  };

  const handleDelete = async () => {
    if (!deleteTarget) {
      return;
    }

    try {
      await deleteDeal.mutateAsync(deleteTarget.id);
      setDeleteTarget(null);
      setFeedback({
        open: true,
        severity: 'success',
        message: 'Deal deleted.',
      });
    } catch (error) {
      if (!isTransportError(error)) {
        setFeedback({
          open: true,
          severity: 'error',
          message: extractErrorMessage(error, 'Delete failed.'),
        });
      }
    }
  };

  const handlePageChange = (page) => {
    setListQuery((current) => ({ ...current, page }));
  };

  const handlePageSizeChange = (pageSize) => {
    setListQuery((current) => ({ ...current, page: 1, pageSize }));
  };

  const handleFilterChange = (field) => (event) => {
    const value = event.target.value;

    setListQuery((current) => ({
      ...current,
      page: 1,
      [field]: value || undefined,
    }));
  };

  const handleResetFilters = () => {
    setListQuery((current) => ({
      page: 1,
      pageSize: current.pageSize,
      stage: undefined,
      companyId: undefined,
    }));
  };

  const dealPage = dealsQuery.data;
  const dealItems = dealPage?.items ?? [];

  return (
    <Stack spacing={3}>
      <DataTableShell
        title="Deals"
        onSearchChange={() => {}}
        onSearchSubmit={(event) => event.preventDefault()}
        onReset={handleResetFilters}
        searchPlaceholder="Filtering is available by stage and company"
        searchValue=""
        filters={(
          <Stack direction={{ xs: 'column', sm: 'row' }} spacing={1.5}>
            <TextField
              select
              size="small"
              label="Stage"
              value={listQuery.stage ?? ''}
              onChange={handleFilterChange('stage')}
              sx={{ minWidth: '11rem' }}
            >
              <MenuItem value="">All stages</MenuItem>
              <MenuItem value="lead">Lead</MenuItem>
              <MenuItem value="qualified">Qualified</MenuItem>
              <MenuItem value="proposal">Proposal</MenuItem>
              <MenuItem value="negotiation">Negotiation</MenuItem>
              <MenuItem value="closed_won">Closed Won</MenuItem>
              <MenuItem value="closed_lost">Closed Lost</MenuItem>
            </TextField>

            <TextField
              select
              size="small"
              label="Company"
              value={listQuery.companyId ?? ''}
              onChange={handleFilterChange('companyId')}
              sx={{ minWidth: '14rem' }}
            >
              <MenuItem value="">All companies</MenuItem>
              {(companiesQuery.data?.items ?? []).map((company) => (
                <MenuItem key={company.id} value={company.id}>
                  {company.name}
                </MenuItem>
              ))}
            </TextField>
          </Stack>
        )}
        actions={(
          <Button
            variant="contained"
            startIcon={<PlusOutlined />}
            onClick={() =>
              setFormState({
                open: true,
                mode: 'create',
                deal: null,
              })
            }
          >
            Add Deal
          </Button>
        )}
        loading={dealsQuery.isLoading}
        error={
          dealsQuery.isError && !isTransportError(dealsQuery.error)
            ? extractErrorMessage(dealsQuery.error, 'Failed to load deals.')
            : null
        }
        isEmpty={!dealsQuery.isLoading && !dealsQuery.isError && dealItems.length === 0}
        emptyTitle="No matching deals"
        emptyDescription="Try selecting a different stage or company filter."
        pagination={
          dealPage && dealPage.total >= 0 ? (
            <Box sx={{ display: 'flex', width: '100%', justifyContent: 'center' }}>
              <DataTablePagination
                page={dealPage.page}
                pageSize={dealPage.pageSize}
                total={dealPage.total}
                totalPages={dealPage.totalPages}
                onPageChange={handlePageChange}
                onPageSizeChange={handlePageSizeChange}
              />
            </Box>
          ) : null
        }
      >
        <DealTable
          deals={dealItems}
          onDelete={setDeleteTarget}

